# -*- coding: utf-8 -*-
# 第 126-150 课内容数据
LESSONS_PART = [

# ============ 第9章 动画系统 (126-145) ============
{"num":126,"title":"动画系统概览与 Animation 窗口","summary":"认识 Unity 动画系统两大工具：Animation 窗口（关键帧）与 Animator（状态机）。","keywords":"动画系统,animation窗口,animator,关键帧,概览","time":"约 13 分钟","difficulty":"入门",
 "objectives":["理解动画系统组成","认识 Animation 窗口","认识 Animator 控制器"],
 "intro":"动画让游戏“活”起来。Unity 动画体系主要由两部分组成：Animation 窗口做“片段动画”，Animator 做“状态切换”。本课建立整体地图。",
 "sections":[
  {"h":"动画系统的两大组件","lead":"先分清“做动画”和“管动画”。",
   "steps":["【Animation 窗口】Window → Animation → Animation：制作“关键帧动画”，像剪辑师逐帧摆姿势，输出一个动画片段（Animation Clip）。","【Animator 组件】给角色添加 Animator 组件，关联一个“动画控制器（Animator Controller）”，负责“什么时候播哪个动画”。","【Animator Controller】Window → Animator 打开：可视化的“状态机”，用状态+过渡管理动画切换。","【流程】用 Animation 窗口做好若干片段 → 在 Animator Controller 里组织状态机 → 挂到角色 Animator 上 → 代码控制参数切换。","【动画片段来源】① Animation 窗口自做；② 外部 FBX 模型自带；③ 商店资源。","【组件】Animator 组件：Controller 槽放控制器、Avatar 槽放骨骼配置。","【播放控制】默认自动播放 Entry 连出的状态；用代码 SetFloat/SetTrigger 等控制切换（第 142 课）。"],
   "tips":[{"t":"note","c":"记忆：Animation 窗口 = 拍素材；Animator 状态机 = 剧本编排。"}]},
  {"h":"打开两个窗口","lead":"把工具调出来。",
   "steps":["【打开 Animation】菜单 Window → Animation → Animation（或 Ctrl+6 快捷键）。","【打开 Animator】菜单 Window → Animation → Animator。","【布局】把两个窗口拖到方便的位置（第 19 课布局技巧）。","【Animation 窗口布局】左侧对象列表、中间时间轴、下方关键帧区域。","【Animator 窗口布局】左侧参数（Parameters）、中间状态图（Base Layer）、左侧 Layers 层级。","先认识界面即可，本课不需要做内容。","【注意】Animation 窗口在“非播放”状态编辑，播放状态看效果。","【版本】TextMeshPro、新 UI 等也会用到动画，先掌握基础。"],
   "tips":[{"t":"note","c":"两个窗口快捷键：Animation 是 Ctrl+6，Animator 在 Window→Animation 菜单里。"}]},
 ],
 "errors":[{"err":"Animation 窗口打不开？","why":"可能被其他窗口遮挡","fix":"Window → Animation → Animation 强制打开；检查标签页。"}],
 "exercise":["打开 Animation 与 Animator 两个窗口","说出动画系统的两大组成部分","明白“做片段”与“管切换”的分工"],
 "summary":"动画系统地图已建立。下一课亲手做一个关键帧动画。"},

{"num":127,"title":"创建第一个关键帧动画","summary":"用 Animation 窗口制作第一个关键帧动画：让方块移动、旋转、变色。","keywords":"关键帧,keyframe,录制动画,animation window,动画制作","time":"约 16 分钟","difficulty":"入门",
 "objectives":["掌握关键帧概念","掌握录制动画流程","保存动画片段"],
 "intro":"关键帧动画 = 在几个时间点摆好“姿势”，Unity 自动补出中间的过渡。本课亲手录一个会跳的方块。",
 "sections":[
  {"h":"关键帧概念","lead":"两个关键帧之间自动补间。",
   "steps":["【关键帧】在某个时间点记录下对象的状态（位置/旋转/缩放/颜色等）。","【补间】Unity 在两个关键帧之间自动生成平滑过渡（动画曲线）。","【例子】第 0 秒方块在左边，第 1 秒在右边——播放时方块从左平滑移动到右。","【时间轴】Animation 窗口中间的水平条是时间轴，单位秒。","【属性】可以给 Transform、材质颜色、灯光强度等几乎所有属性做动画。","【动画片段】做好的动画保存为 .anim 文件（Animation Clip），可复用。","【播放】挂到对象上后自动播放（如果 Animator 控制器只含这个状态）。"],
   "tips":[{"t":"note","c":"原理一句话：摆几个关键姿势，中间过渡交给电脑。"}]},
  {"h":"录制方块跳动动画","lead":"动手做。",
   "steps":["场景里放一个 Cube，选中它。","打开 Animation 窗口（Ctrl+6），点击窗口中的【Create】按钮。","命名动画为 JumpAnim，保存到 Assets/Animations 文件夹。","Unity 自动给 Cube 添加 Animator 组件并创建控制器。","【录制】点 Animation 窗口里的红色【● 录制按钮】，开始记录。","【第 0 秒】点击时间轴 0 秒处，选中 Cube，在场景里把它摆到起始位置（原点），点“添加关键帧”（或直接改动属性自动记录）。","【第 0.5 秒】点击时间轴 0.5 秒处，把 Cube 沿 Y 轴向上移动 2 米（位置变高），自动生成关键帧。","【第 1 秒】点击 1 秒处，把 Cube 移回起始位置。","【停止录制】再次点击红色 ● 停止。","【预览】点 Animation 窗口的播放按钮 ▶，看到方块跳起再落回！","【保存】动画片段已自动保存为 .anim。","【注意】录制时改动的位置/属性才会生成关键帧。"],
   "tips":[{"t":"danger","c":"记得停止录制（● 再点一次），否则所有改动都会记录成关键帧。"}]},
 ],
 "errors":[{"err":"录制的动画没有效果？","why":"没在录制模式，或没在不同时间点加关键帧","fix":"确认红色 ● 处于激活（录制）状态；确认在 0、0.5、1 秒都摆了不同状态。"}],
 "exercise":["做一个方块跳起再落下的动画","再做一个方块原地旋转 360 度的动画","把两个动画片段分别保存"],
 "summary":"第一个关键帧动画完成！下一课学动画曲线。"},

{"num":128,"title":"动画曲线 Animation Curve","summary":"掌握动画曲线：调整关键帧之间的运动节奏，做出加速、缓动等手感。","keywords":"动画曲线,curve,曲线编辑,缓动,贝塞尔,速度控制","time":"约 13 分钟","difficulty":"入门",
 "objectives":["理解动画曲线的意义","掌握曲线编辑","做出缓动效果"],
 "intro":"关键帧之间怎么过渡？直线过渡生硬，曲线过渡自然。本课用曲线控制运动节奏。",
 "sections":[
  {"h":"曲线视图","lead":"每条属性一条曲线。",
   "steps":["打开 Animation 窗口，选中做好的动画片段，在下方属性列表里能看到每条属性（如 Position.y、Rotation.z）。","每条属性右侧是一个【曲线图标】，点击后窗口切换到“曲线视图”。","曲线视图横轴=时间、纵轴=属性值。","【直线】两个关键帧之间是直线=匀速过渡。","【曲线】关键帧端点有“手柄”，拖动改变曲线弧度，实现“先快后慢/先慢后快”。","【右击关键帧】出现菜单：Auto（自动平滑）、Free Smooth、Flat（平坦）、Linear（线性）、Constant（恒定）。","【Flat 平坦】过渡平滑减速（常用默认）。","【Linear】直线匀速。","【Constant】到点瞬间跳变（不过渡）。"],
   "tips":[{"t":"note","c":"大部分自然动作用 Auto/Flat（缓入缓出）；机械动作用 Linear。"}]},
  {"h":"做出缓动效果","lead":"让跳跃更自然。",
   "steps":["选中之前做的 JumpAnim 片段，进入曲线视图。","选中 Position.y 曲线的两个关键帧，把 Tangent 设为 Flat（或用曲线编辑手柄拉出弧形）。","播放预览：方块起跳“先快后慢”、落地“先快后慢”，比生硬直线自然多了。","【缓入】关键帧左侧手柄拖成水平 = 起步慢。","【缓出】右侧手柄拖成水平 = 到点减速。","【整体调节】双击曲线可全选编辑；用缩放工具整体缩放曲线。","【复制曲线】右键 → Copy Curve 可复制到其他片段。","【注意】曲线只影响“过渡的形状”，不改变关键帧的数值。"],
   "tips":[{"t":"success","c":"曲线手感三件套：Flat 平滑、Linear 机械、Constant 跳变，按需选用。"}]},
 ],
 "errors":[{"err":"曲线视图找不到？","why":"没点属性右侧的曲线图标","fix":"在 Animation 窗口选中属性行，点右侧曲线按钮进入曲线模式。"}],
 "exercise":["把跳跃动画的曲线调成平滑缓动","对比 Linear 与 Flat 的视觉差异","做一个 Constant 跳变的变色动画"],
 "summary":"动画曲线已掌握。下一课学动画剪辑的属性。"},

{"num":129,"title":"动画剪辑 AnimationClip 属性","summary":"掌握动画片段的循环、速度、镜像等属性，以及片段的管理。","keywords":"animationclip,动画剪辑,循环,loop,播放速度,镜像","time":"约 12 分钟","difficulty":"入门",
 "objectives":["掌握动画片段属性","掌握循环设置","掌握速度与镜像"],
 "intro":"一个动画片段除了“内容”，还有很多播放属性：是否循环、速度快慢、是否镜像。本课讲清楚。",
 "sections":[
  {"h":"动画片段属性","lead":"在 Project 里选中 .anim 文件看属性。",
   "steps":["在 Project 找到动画片段（.anim 文件），选中它，Inspector 显示其属性。","【Loop Time 循环】勾选后动画循环播放（走路、待机必勾；一次性动作如跳跃不勾）。","【Loop Pose】循环时保证首尾姿势衔接（走路等循环动作勾选更顺）。","【Cycle Offset】循环的相位偏移（多个角色走路错开）。","【Root Transform Rotation/Position】控制根运动（第 140 课）。","【Bake Into Pose】等进阶选项，先了解。","【Speed】片段默认速度 1，可在 Animator 里用参数乘速度（第 142 课）。","【播放时长】片段时长在 Animation 窗口时间轴看到。"],
   "tips":[{"t":"note","c":"铁律：循环动作勾 Loop Time，一次性动作别勾，否则跳跃会“鬼畜”循环。"}]},
  {"h":"片段管理与多片段","lead":"一个对象多个动画。",
   "steps":["一个对象可以有多个动画片段（.anim），通过 Animator 控制器切换（第 130-133 课）。","【创建新片段】在 Animation 窗口左上角下拉选择“创建新剪辑”，命名并保存。","【切换片段】下拉选择已有片段即可编辑。","【重命名/复制】在 Project 里操作 .anim 文件。","【外部动画】FBX 模型自带的动画可拆出来用（第 37 课动画页签）。","【预览】选中 .anim，Inspector 顶部点播放 ▶ 预览。","【复用】同一片段给多个对象用（共享），修改片段全体生效。","【注意】片段引用的属性（如 Transform）要匹配目标对象，否则警告。"],
   "tips":[{"t":"success","c":"先规划好“这个对象需要哪些片段”（待机/走路/跳跃…），再逐个做，事半功倍。"}]},
 ],
 "errors":[{"err":"动画不循环，播一遍就停？","why":"Loop Time 未勾选","fix":"选中 .anim 在 Inspector 勾选 Loop Time（循环动作才需要）。"}],
 "exercise":["给一个动画片段设置循环","制作两个片段并在 Animation 窗口切换编辑","预览不同片段"],
 "summary":"动画剪辑属性已掌握。下一课学 Animator 与 Animator Controller。"},

{"num":130,"title":"Animator 与 Animator Controller","summary":"掌握 Animator 组件与控制器：创建、关联、基础状态机概念。","keywords":"animator,animator controller,动画控制器,状态机,挂载","time":"约 14 分钟","difficulty":"入门",
 "objectives":["理解 Animator 组件","创建动画控制器","关联片段到控制器"],
 "intro":"Animation 片段做出来了，怎么“按需播放”？靠 Animator Controller 状态机。本课搭起这个“指挥中心”。",
 "sections":[
  {"h":"Animator 组件","lead":"挂在角色上的“播放器”。",
   "steps":["Animator 组件负责播放动画，挂在要动画的对象上（角色、UI、机械）。","【添加】选中对象 → Add Component → 搜 Animator → 添加。","【Controller 槽】必须关联一个动画控制器（Animator Controller 资产）。","【Avatar 槽】人形动画（Humanoid）需要 Avatar（第 138 课）；通用动画可不填。","【Apply Root Motion】是否应用根运动（第 140 课）。","【Update Mode】Normal（每帧）、Animate Physics（配合物理）、Unscaled Time（不受暂停影响）。","【Culling Mode】Always Animate（始终动画）、Cull Update Transforms（画面外不更新，省性能）。"],
   "tips":[{"t":"note","c":"Animator 组件 = 硬件；Controller 资产 = 软件。两者配合才能播动画。"}]},
  {"h":"创建 Animator Controller","lead":"搭建状态机雏形。",
   "steps":["在 Project 右键 → Create → Animator Controller，命名 PlayerAnim。","【双击打开】双击该控制器，打开 Animator 窗口（状态机视图）。","【默认结构】自动有 Entry（入口）与 Any State（任意状态）两个灰色节点。","【添加状态】右键空白处 → Create State → Empty，创建“Idle”状态；重复创建“Walk”“Jump”等。","【绑定片段】选中 Idle 状态，在 Inspector 的 Motion 槽里拖入你的动画片段（.anim）。","【入口连接】默认 Entry 会自动连到第一个状态；也可右键 Entry → Make Transition 连到指定状态。","【初始状态】绿色边框的状态是默认状态（播放时最先进入）。","【保存】控制器自动保存（Ctrl+S）。","【挂载】把 PlayerAnim 拖到角色的 Animator → Controller 槽。","播放：角色播放初始状态的动画。"],
   "tips":[{"t":"success","c":"状态机三要素：状态（State 节点）、过渡（Transition 箭头）、参数（Parameters）——下一课逐一展开。"}]},
 ],
 "errors":[{"err":"角色不播放动画？","why":"Controller 未挂载、或状态没有 Motion、或默认状态未连接","fix":"确认 Animator 的 Controller 已关联；状态有 Motion；Entry 连到了某状态。"}],
 "exercise":["创建 PlayerAnim 控制器并挂到角色","创建 Idle/Walk 两个状态并绑定动画","设置默认状态并播放验证"],
 "summary":"Animator 与控制器已掌握。下一课深入状态机。"},

{"num":131,"title":"动画状态机 Animator State Machine","summary":"深入状态机：多状态、Any State、子状态机、状态行为，掌握状态切换逻辑。","keywords":"状态机,state machine,状态,anystate,子状态机,状态行为","time":"约 15 分钟","difficulty":"入门",
 "objectives":["理解状态机运作","掌握 Any State","掌握子状态机与状态行为"],
 "intro":"状态机是动画的“大脑”：当前播什么、何时切到别的。本课把状态机的全部机制讲透。",
 "sections":[
  {"h":"状态机的运作方式","lead":"“当前状态 + 过渡条件”决定播放。",
   "steps":["【状态 State】一个节点 = 一种动画（待机、走路、攻击）。","【当前状态】任意时刻只有一个状态在播放（Base Layer）。","【过渡 Transition】状态之间的箭头，带条件，满足即切换。","【判断】每帧检查当前状态连出的过渡条件，满足就切到目标状态。","【默认状态】绿色边框的是初始状态。","【状态命名】清晰命名（Idle、Walk、Jump、Attack）。","【状态属性】选中状态，Inspector 有 Motion（动画）、Speed（播放速度）、Mirror（镜像）等。","【Write Defaults】勾选默认：切换时恢复未动画的属性（一般保持默认）。"],
   "tips":[{"t":"note","c":"状态机 = 一张“地图”：你在哪（当前状态）、怎么走（过渡条件）。"}]},
  {"h":"Any State 与子状态机","lead":"进阶节点。",
   "steps":["【Any State 任意状态】灰色节点：从“任何状态”都可出发的过渡。适合“随时可打断”的动作，如受击、死亡。","用法：Any State → Dead 状态，条件 IsDead=true。这样不管在走还是在跳，一死就切死亡。","【注意】Any State 的过渡优先级高于普通过渡，且要小心冲突。","【子状态机 Sub-State Machine】把一组相关状态打包成一个节点，用于复杂角色（如“移动组”里含走/跑/冲刺）。","【创建】右键 → Create Sub-State Machine。","【状态行为 StateMachineBehaviour】给状态挂“行为脚本”（进入/退出/更新回调），进阶（第 142 课补充）。","【层级 Layers】动画层（第 136 课）管理上下半身分开的动画。","【实战】搭建“待机/走路/跳跃/攻击/死亡”五个状态的完整状态机。"],
   "tips":[{"t":"success","c":"实战状态机：Idle/Walk/Jump/Attack/Dead + Any State 死亡过渡，覆盖 90% 角色需求。"}]},
 ],
 "errors":[{"err":"动画状态互相“打架”？","why":"过渡条件冲突或优先级混乱","fix":"用参数区分；把高优先级/紧急过渡用 Any State；检查过渡条件是否互斥。"}],
 "exercise":["搭建 5 状态状态机","用 Any State 连接死亡过渡","给状态设置不同播放速度"],
 "summary":"状态机已掌握。下一课学动画参数。"},

{"num":132,"title":"动画参数 Parameters","summary":"掌握 Animator 参数：Float/Int/Bool/Trigger 四类，用参数驱动状态切换。","keywords":"动画参数,parameters,setfloat,setbool,settrigger,setint","time":"约 14 分钟","difficulty":"入门",
 "objectives":["掌握四种参数类型","掌握代码设置参数","用参数控制切换"],
 "intro":"状态之间“凭什么切”？凭参数。代码往参数里写值，状态机看值决定切不切。本课讲透参数。",
 "sections":[
  {"h":"四种参数类型","lead":"按数据类型选。",
   "steps":["在 Animator 窗口左侧【Parameters】面板点【+】添加参数。","【Float 浮点】连续数值：速度、血量。例：Speed。","【Int 整数】离散数值：等级、阶段。例：State。","【Bool 布尔】开关：是否移动、是否死亡。例：IsWalking。","【Trigger 触发器】一次性“脉冲”：按一下就触发然后自动复位。例：Attack、Jump。","【用途】Float/Bool 用于“持续性”切换；Trigger 用于“一次性”动作。","【参数命名】与代码一致，小驼峰或大驼峰都行，但全项目统一。","【参数面板】每个参数可设默认值。"],
   "tips":[{"t":"note","c":"参数选择口诀：连续值用 Float、开关用 Bool、一次性动作用 Trigger。"}]},
  {"h":"代码设置参数","lead":"Set 系列方法。",
   "steps":["在脚本里先拿 Animator：private Animator anim; void Awake() { anim = GetComponent<Animator>(); }","【SetFloat】anim.SetFloat(\"Speed\", 5f);","【SetInt】anim.SetInt(\"State\", 1);","【SetBool】anim.SetBool(\"IsWalking\", true);","【SetTrigger】anim.SetTrigger(\"Attack\"); 触发后自动复位（也可 ResetTrigger 手动复位）。","【读参数】float s = anim.GetFloat(\"Speed\");","【平滑 Float】anim.SetFloat(\"Speed\", value, 0.1f, Time.deltaTime); 带阻尼平滑（走路→跑步渐变）。","【参数名匹配】代码里的名字必须与 Animator 面板完全一致，否则无效（写错不报错、动画不动）。","【实战】移动时 SetBool(\"IsWalking\", true)、停下 false；按攻击键 SetTrigger(\"Attack\")。","【注意】SetTrigger 在“目标状态没连对应过渡”时无效果。"],
   "tips":[{"t":"danger","c":"参数名写错是“动画不动”的头号原因：不报错但没反应，务必核对拼写。"}]},
 ],
 "errors":[{"err":"SetTrigger 没反应？","why":"参数名不一致，或过渡条件没用该 Trigger","fix":"核对参数名；确认有“触发该 Trigger”的过渡从当前状态出发。"}],
 "exercise":["添加 Float/Bool/Trigger 三类参数","用代码 SetFloat 控制 Speed 切换走路/跑步","用 SetTrigger 触发攻击动画"],
 "summary":"动画参数已掌握。下一课学动画过渡 Transitions。"},

{"num":133,"title":"动画过渡 Transitions 与条件","summary":"掌握过渡的设置：触发条件、Has Exit Time、过渡时间、打断与优先级。","keywords":"过渡,transition,has exit time,过渡时间,条件,打断","time":"约 14 分钟","difficulty":"入门",
 "objectives":["掌握过渡条件设置","理解 Has Exit Time","掌握过渡时长与打断"],
 "intro":"状态之间的“桥”就是过渡（Transition）。桥的通行规则（条件、时间、打断）决定动画衔接是否自然。",
 "sections":[
  {"h":"创建与配置过渡","lead":"连一条“桥”。",
   "steps":["【创建过渡】在 Animator 里右键状态A → Make Transition → 点击状态B，生成 A→B 的箭头。","【选中箭头】点击箭头，右侧 Inspector 显示过渡属性。","【Conditions 条件】点【+】添加条件：选择参数、比较方式（Greater/Less/Equals/Not Equals）、填数值。","例：Speed Greater 0.1 时从 Idle 切到 Walk。","【Has Exit Time】勾选：当前动画“播完/播到退出时间”才允许过渡（适合动作完成后的衔接）。","取消勾选：条件满足立即过渡（适合即时响应，如走路立刻变攻击）。","【Transition Duration】过渡时长：0.1-0.2 秒的交叉融合让切换自然。","【Transition Offset】从目标动画的哪个时间点开始播（进阶）。"],
   "tips":[{"t":"note","c":"Has Exit Time 勾选=播完才走（完整动作）；不勾=立即走（实时响应）。多数游戏动作选不勾。"}]},
  {"h":"打断与优先级","lead":"让过渡可控。",
   "steps":["【打断】默认过渡可被其他过渡打断。","【Interruption Source】下拉：None（不可打断）、Current State（被当前状态的其他过渡打断）、Next State 等（进阶）。","【优先级】多个过渡条件同时满足时，Animator 按“过渡箭头列表的顺序”选择（越靠上越优先）。","调整顺序：在状态 Inspector 的 Transitions 列表里拖动。","【Any State 过渡】优先级最高，用于紧急打断（死亡、受击）。","【优化】条件尽量互斥、减少同时满足的情况，状态机更稳定。","【过渡预览】点 Play 播放，看过渡是否自然，调整 Duration。","【常见问题】“动画卡住不动”多因过渡条件永远不满足或 Duration 过大。","【实战】Idle↔Walk、Walk→Jump、Jump→Idle（落地）、Any→Dead。"],
   "tips":[{"t":"success","c":"过渡三要素：条件（何时切）+ 时长（多自然）+ 打断（谁优先）。调好它们动画才“听话”。"}]},
 ],
 "errors":[{"err":"动画切换生硬/卡顿？","why":"Transition Duration 为 0 或过渡未配置好","fix":"把 Duration 设 0.1-0.2；确认条件逻辑正确；必要时用 Blend Tree（第 134 课）。"}],
 "exercise":["搭建 Idle→Walk 的条件过渡","设置 Jump 的过渡与落地回 Idle","调整 Transition Duration 体验自然度"],
 "summary":"过渡已掌握。下一课学混合树 Blend Tree。"},

{"num":134,"title":"动画混合树 Blend Tree","summary":"用混合树把多个动画按参数平滑混合，实现“走路与跑步无缝过渡”。","keywords":"blend tree,混合树,1d混合,2d混合,动画融合","time":"约 15 分钟","difficulty":"入门",
 "objectives":["理解混合树的作用","掌握 1D 混合树","掌握 2D 混合树"],
 "intro":"走路和跑步之间“无缝过渡”不用做两个状态，用混合树按速度参数平滑融合。这是角色动画的进阶关键。",
 "sections":[
  {"h":"1D 混合树","lead":"按一个参数混合多个动画。",
   "steps":["在 Animator 窗口右键 → Create State → From New Blend Tree，创建一个混合树节点。","双击该节点进入混合树编辑界面。","【Blend Type】选 1D。","【Parameters】选择驱动参数（如 Speed）。","【添加动画】点【+】→ Add Motion Field，添加动画片段；重复添加 Idle（速度0）、Walk（速度0.5）、Run（速度1）。","【Threshold 阈值】为每个动画设对应参数值（0 / 0.5 / 1）。","【预览】调整 Speed 参数，动画在 Idle/Walk/Run 间平滑融合。","【注意】混合树节点在状态机里是一个“状态”，由过渡进入。","【优势】不用为走路/跑步各做过渡，参数连续变化动画无缝。"],
   "tips":[{"t":"note","c":"1D 混合 = 一维滑块（速度）控制多段动画融合，人物移动必备。"}]},
  {"h":"2D 混合树","lead":"按两个参数做方向混合。",
   "steps":["创建混合树，Blend Type 选 2D Simple Directional（或 Freeform）。","【Parameters】选两个参数（如 MoveX、MoveY，即输入方向）。","【添加动画】添加 4 个方向动画：前走（0,1）、后走（0,-1）、左走（-1,0）、右走（1,0）。","为每个动画设 Position（x,y）对应参数值。","【效果】输入任意方向，动画按方向平滑混合（斜走也是多个动画融合）。","【2D Freeform】更自由的分布，适合复杂方向（进阶）。","【注意】2D 混合对“八方向移动”角色特别有效。","【结合 Blend Tree】常用结构：状态机里一个“Move”混合树状态 + Idle 状态。","【代码】SetFloat 两个方向参数即可。"],
   "tips":[{"t":"success","c":"混合树让“连续变化”的动画（走路↔跑步、方向）自动平滑，是现代角色动画标配。"}]},
 ],
 "errors":[{"err":"混合树只播一个动画？","why":"参数没变化或阈值设置不当","fix":"确认驱动参数被代码更新；检查 Threshold 顺序递增；检查动画片段是否被正确添加。"}],
 "exercise":["创建 Idle/Walk/Run 的 1D 混合树","用 Speed 参数驱动，播放看混合效果","（进阶）做 2D 方向混合"],
 "summary":"混合树已掌握。下一课学动画事件。"},

{"num":135,"title":"动画事件 Animation Event","summary":"在动画特定帧触发代码事件：脚步落地、音效、攻击判定等。","keywords":"动画事件,animation event,事件,关键帧回调,攻击判定","time":"约 13 分钟","difficulty":"入门",
 "objectives":["理解动画事件原理","掌握添加动画事件","实现脚步与攻击判定"],
 "intro":"“动画里脚落地的瞬间要响脚步声”“挥刀到一半要判定伤害”——动画事件在特定帧“叫”代码执行。",
 "sections":[
  {"h":"动画事件基础","lead":"在时间轴某点“按铃”。",
   "steps":["动画事件（Animation Event）在动画播放到某帧时调用指定脚本方法。","【适用】脚步音效、攻击命中判定、粒子特效时机、音效同步。","【前提】动画片段能添加事件（Animation 窗口里）。","【方法要求】被调用的方法要挂在“播放该动画的对象”上，且是 public。","【方法签名】可以是无参方法，也可带 1 个参数（float/int/string/object/AnimationEvent）。","【注意事项】事件方法名拼错不会报错但不会触发，要核对。","【触发时机】事件在动画播放到对应时间点时触发。"],
   "tips":[{"t":"note","c":"动画事件 = “定时呼叫”：动画替你计时，到点叫你的方法。"}]},
  {"h":"添加事件实战","lead":"给走路动画加脚步事件。",
   "steps":["在 Animation 窗口选中“走路”动画片段，播放到“脚落地”的时间点。","【添加事件】在时间轴上方点【右键】→【Add Animation Event】（或点顶部的事件标记按钮）。","时间轴上出现一个白色菱形标记。","【绑定方法】选中菱形标记，在 Inspector 里：Function 下拉选择要调用的方法名（如 FootStep）。","参数（string/float/int/object）可填，如 “left”。","【写方法】在播放动画的角色脚本里写：","public void FootStep(string foot) { Debug.Log(\"脚步：\" + foot); AudioSource.PlayClipAtPoint(stepSound, transform.position); }","【测试】播放走路动画，脚落地瞬间输出“脚步”并播放音效。","【攻击判定】在挥刀动画的“击中帧”加事件调用 DealDamage()。","【多个事件】同一时间轴可加多个事件（音效+特效+判定）。","【注意】事件时间要精确，拖动菱形微调。"],
   "tips":[{"t":"success","c":"动画事件= 在关键帧放“闹钟”。攻击/脚步/投掷这些“时机敏感”逻辑全靠它。"}]},
 ],
 "errors":[{"err":"事件没触发？","why":"方法名不一致、方法没挂在该对象、或没点中事件标记","fix":"核对 Function 拼写；确认方法所在脚本挂在播放动画的对象上；检查事件标记位置。"}],
 "exercise":["给走路动画加脚步事件并绑定方法","给攻击动画加一个伤害判定事件","（进阶）给事件传不同参数区分左右脚"],
 "summary":"动画事件已掌握。下一课学动画层。"},

{"num":136,"title":"动画层 Animation Layer","summary":"掌握动画层：上下半身分层动画、遮罩与权重，实现“边走边攻击”。","keywords":"动画层,animation layer,层级,遮罩,avatar mask,权重","time":"约 14 分钟","difficulty":"入门",
 "objectives":["理解动画层原理","掌握创建动画层","掌握 Avatar Mask 遮罩"],
 "intro":"“上半身挥剑、下半身同时走路”是很多游戏的需求。动画层（Layer）把身体拆成多层独立动画。",
 "sections":[
  {"h":"动画层原理","lead":"多个动画叠加播放。",
   "steps":["Animator 左侧有【Layers 层级】面板，默认有 Base Layer（基础层）。","【添加层】点层级面板的 + 号，新建一个 Layer（如 UpperBody）。","【权重】每层有 Weight（0-1）：控制该层动画的混合程度。Base Layer 通常 Weight=1。","【合成】多层动画按权重叠加：下层走路 + 上层攻击 = 边走边攻击。","【Mask 遮罩】给上层设置 Avatar Mask：指定“哪些骨骼参与该层动画”。","【创建 Mask】Project 右键 → Create → Avatar Mask → 打开，勾选要控制的骨骼（上半身）。","【指定 Mask】在 Layer 的 Mask 槽里拖入 Avatar Mask。","【默认层】Base Layer 权重固定为 1，其他层默认 0（需代码开）。","【应用】上层做“攻击/挥手/拿枪”（Mask 上半身），下层做“走路/跑步”。"],
   "tips":[{"t":"note","c":"动画层 = 身体分层：Base 管下半身移动，UpperBody 管上半身动作，用 Mask 拆开。"}]},
  {"h":"层权重代码控制","lead":"让上层“开/关”。",
   "steps":["Animator 的 Layers 面板每层有 Index（0=Base，1=UpperBody...）。","【权重】anim.SetLayerWeight(1, 1f); // 打开上层","anim.SetLayerWeight(1, 0f); // 关闭上层","【平滑开关】用 Lerp 平滑过渡权重：","anim.SetLayerWeight(1, Mathf.Lerp(anim.GetLayerWeight(1), 1f, Time.deltaTime * 10f));","【层内状态机】每层都是独立的状态机，有独立 Entry/Any State。","【写代码】在层状态机里给“攻击”状态设条件，进入攻击时开权重，退出时关。","【实战】按攻击键：Trigger 攻击 → 上层播攻击动画 → 权重平滑到 1 → 结束权重回 0。","【注意】Mask 不匹配时上层动画可能“不动”，检查 Mask 勾选范围。","【性能】层越多越耗，按需使用。"],
   "tips":[{"t":"success","c":"动画层 + 权重 = “局部动画”的标准做法，常见于 3D 动作游戏。"}]},
 ],
 "errors":[{"err":"上层动画没效果？","why":"权重为 0、或 Mask 没遮到对应骨骼、或层没设置好状态","fix":"确认 SetLayerWeight 开了；Mask 勾选上半身骨骼；层内状态机有有效动画。"}],
 "exercise":["创建 UpperBody 层并设 Mask（上半身）","在下层做走路、上层做攻击动画","用权重代码实现“边走边攻击”"],
 "summary":"动画层已掌握。下一课学骨骼动画与绑定。"},

{"num":137,"title":"骨骼动画与骨骼绑定","summary":"理解骨骼动画原理、骨骼层级、绑定与动画如何驱动骨骼。","keywords":"骨骼动画,骨骼绑定,骨骼,skeleton,skin,bone","time":"约 13 分钟","difficulty":"入门",
 "objectives":["理解骨骼动画原理","认识骨骼层级","理解蒙皮与绑定"],
 "intro":"3D 角色动画的本质是“驱动骨骼，骨骼带动网格”。本课把骨骼动画的内部结构讲清楚。",
 "sections":[
  {"h":"骨骼动画原理","lead":"“骨骼带动皮”。",
   "steps":["【骨骼 Skeleton】模型内部有一副“骨架”，由一根根 Bone（骨骼）组成，层级相连（手臂骨连在肩骨下）。","【蒙皮 Skinning】模型表面的“皮”（网格顶点）绑定到骨骼上，每根骨骼影响一片顶点。","【动画原理】动画片段记录每根骨骼每个时间点的旋转/位置 → 播放时骨骼运动 → 顶点跟着动 → 皮变形。","【Hierarchy 里】导入的带骨骼模型，场景中会看到 Bone 对象（Transform 层级）。","【优点】一套骨骼配多套动画（换动作不用改模型）；骨骼可复用（换皮）。","【查看骨骼】选中模型在场景里看 Hierarchy 的骨骼树。","【骨骼重定向】不同模型用同一套动画（第 139 课）。"],
   "tips":[{"t":"note","c":"一句话：骨骼是“骨架”，动画是“骨骼的运动剧本”，网格是“跟着动的皮”。"}]},
  {"h":"骨骼绑定与层级","lead":"认识骨骼树。",
   "steps":["导入带动画的 FBX 模型（第 36-37 课），拖进场景。","在 Hierarchy 展开模型，能看到骨骼对象（如 Hips、Spine、Arm_L 等），呈树状层级。","根骨通常是 Hips（髋部），子骨骼依次连到脊柱、头、四肢。","【Transform 关系】子骨骼位置相对父骨骼（局部坐标），旋转父骨骼，子骨骼跟随。","【动画驱动】Animator 在运行时根据动画片段更新每根骨骼的 Transform。","【SkinnedMeshRenderer】模型表面的渲染组件：负责“蒙皮”——根据骨骼 Transform 变形网格。","【注意】不要在运行时手动移动骨骼 Transform（会被动画覆盖）。","【选模型】新手优先用“人形（Humanoid）”模型，方便复用动画与重定向。"],
   "tips":[{"t":"warn","c":"不要直接操作骨骼 Transform 做动画（应通过 Animator/动画片段）；骨骼动画由系统驱动。"}]},
 ],
 "errors":[{"err":"模型动了但“皮”没跟着动？","why":"SkinnedMeshRenderer 的骨骼引用异常","fix":"检查 SkinnedMeshRenderer 的 Bones 列表是否完整引用；重新导入模型。"}],
 "exercise":["导入一个带动画的人形模型并查看骨骼树","说出骨骼与蒙皮的关系","理解“动画驱动骨骼、骨骼带动网格”"],
 "summary":"骨骼动画原理已掌握。下一课学 Avatar 与人形动画。"},

{"num":138,"title":"Avatar 与人形动画","summary":"掌握 Avatar 配置：人形骨骼映射，让 Unity 识别角色骨骼并复用人形动画。","keywords":"avatar,人形动画,humanoid,骨骼映射,configure avatar","time":"约 14 分钟","difficulty":"入门",
 "objectives":["理解 Avatar 作用","掌握人形配置","正确设置模型 Rig"],
 "intro":"Unity 的“人形”能力：只要骨骼对齐标准模板，任何角色都能复用同一套人类动画（走路、跑步、挥手）。关键在 Avatar。",
 "sections":[
  {"h":"Avatar 与 Rig 设置","lead":"导入模型时先设对 Rig。",
   "steps":["选中模型文件，Inspector →【Rig】页签。","【Animation Type】选【Humanoid】（人形）。","下方出现【Avatar Definition】：选 Create From This Model（从此模型创建 Avatar）。","点右下角【Apply 应用】。","Unity 自动创建 Avatar（一个 .avatar 资产），并尝试自动匹配骨骼。","若骨骼命名标准，自动匹配成功（绿色对勾）；否则需手动配置（下一步）。","【Generic 通用】非人形模型用 Generic 动画类型（动物、机械）。","【None】不需要动画的静态模型。","【注意】人形动画（官方商店的动作资源）大多只兼容 Humanoid。"],
   "tips":[{"t":"note","c":"想复用人形动画（走路/跑步/攻击），模型必须设成 Humanoid 并生成 Avatar。"}]},
  {"h":"配置 Avatar 骨骼映射","lead":"自动匹配失败时手动指定。",
   "steps":["在 Rig 页签点【Configure Avatar… 配置】按钮，进入 Avatar 配置界面。","场景变灰，显示模型与骨骼系统（Mapping 映射面板）。","右侧列出“标准人形骨骼”（Hips、Spine、Head、Shoulder、Upper Arm 等）。","绿色对勾 = 已自动匹配；红色感叹号 = 未匹配。","【手动指定】点未匹配项（如 Left Upper Leg），再在场景中点击对应的骨骼对象（黄色高亮的可点），建立映射。","【一键自动】点击【Mapping】面板右上角的【Automap】按钮，尝试自动匹配。","【骨骼预览】点击骨骼项，场景中对应骨骼高亮。","【完成】配置完点【Done】，保存 Avatar。","【验证】配置成功后，动画可正常驱动；可导入官方“第三方动画”测试重定向。","【注意】映射错误会导致动画扭曲，务必保证四肢/头部对应。"],
   "tips":[{"t":"success","c":"Avatar 配置 = 把“我的骨骼”翻译成“Unity 标准人形骨骼”，翻译对了动画就通用。"}]},
 ],
 "errors":[{"err":"动画严重扭曲/错位？","why":"Avatar 骨骼映射错误","fix":"重新 Configure Avatar，逐个修正映射；或换骨骼命名标准的模型。"}],
 "exercise":["把一个人形模型设为 Humanoid 并生成 Avatar","打开 Configure Avatar 查看映射状态","修正未匹配的骨骼映射"],
 "summary":"Avatar 与人形动画已掌握。下一课学动画重定向。"},

{"num":139,"title":"动画重定向 Avatar Retargeting","summary":"让不同角色复用同一套人形动画，实现“换皮不换动作”。","keywords":"动画重定向,retargeting,复用动画,换皮,humanoid动画","time":"约 13 分钟","difficulty":"入门",
 "objectives":["理解重定向原理","掌握复用动画","实现不同角色共用动作"],
 "intro":"你有 3 个不同体型/骨架的 NPC，只想做一套走路动画给它们共用——靠“动画重定向”。这是人形系统的王牌功能。",
 "sections":[
  {"h":"重定向原理","lead":"标准骨架做“翻译”。",
   "steps":["【原理】Humanoid 动画记录的是“标准人形骨骼”的运动。","播放时，Unity 把标准骨骼运动“翻译”到目标模型的 Avatar 映射上。","所以只要两个模型都成功配置了 Humanoid Avatar，就能共用同一套动画。","【示例】把“英雄”的走路动画给“矮人”“精灵”用，动作自动适配各自的体型。","【前提】两个模型都要：Rig 设 Humanoid + Avatar 映射正确。","【关键词】Retargeting（重定向）、Humanoid 动画库。","【注意】体型差异过大（人 vs 四足）不能重定向，需要 Generic。","【优势】动画资产一次制作、全局复用，极大省工作量。"],
   "tips":[{"t":"note","c":"重定向 = 标准骨架做中间翻译：只要“会翻译”，谁都能穿同一件“动作外衣”。"}]},
  {"h":"实战：复用动画","lead":"把动画给另一个角色用。",
   "steps":["【准备】导入两个 Humanoid 模型：ModelA（带动画）、ModelB（无动画）。","确认 ModelA 的动画片段已在 Rig/Animation 页签导入（第 37 课）。","【把动画给 ModelB】在 Project 选中 ModelB 的模型，双击进入其 Animator Controller（或新建控制器）。","在控制器的状态 Motion 槽里，拖入 ModelA 的动画片段（.anim 或模型自带的 clip）。","【拖模型动画】展开 ModelA 的 .fbx，把里面的动画拖到 ModelB 控制器的状态里。","【播放】ModelB 播放 ModelA 的动画，自动适配 ModelB 的骨骼！","【注意】动画片段的“人类动作”会按 ModelB 的 Avatar 重新解释。","【第三方动画】官方商店/资源库的 Humanoid 动画都可如此复用。","【Avatar Mask】配合第 136 课做局部复用（只走路不挥手）。","【验证】对比两个角色动作是否一致自然。"],
   "tips":[{"t":"success","c":"一劳永逸：做一套“人类动作库”，所有角色共用。这也是多数动作游戏的资源策略。"}]},
 ],
 "errors":[{"err":"重定向后动画扭曲？","why":"其中一个模型 Avatar 映射错误","fix":"重新 Configure Avatar 修正；确认两者都是 Humanoid。"}],
 "exercise":["导入两个不同模型并都设为 Humanoid","把 A 的动画给 B 用并验证","说出重定向的三个前提"],
 "summary":"动画重定向已掌握。下一课学 Root Motion 根运动。"},

{"num":140,"title":"Root Motion 根运动","summary":"掌握 Root Motion：让动画本身带动角色位移（跑、跳的位移来自动画而非代码）。","keywords":"root motion,根运动,动画位移,apply root motion,动画驱动移动","time":"约 13 分钟","difficulty":"入门",
 "objectives":["理解 Root Motion 概念","掌握开启与关闭","理解与代码移动的关系"],
 "intro":"有的游戏角色移动全靠代码，有的靠“动画自带位移”（跑动画会带着角色前进）。后者就是 Root Motion。",
 "sections":[
  {"h":"什么是 Root Motion","lead":"动画“拖着人走”。",
   "steps":["【普通方式】动画在原地播放，位移由代码控制（transform.position += ...）。","【Root Motion】动画片段本身记录了“根骨（Root）”的位移，播放时带动整个角色移动。","【效果】跑步动画自带前进，播放时角色自动向前跑。","【优点】动作与位移完美同步（尤其跳跃、翻滚这类“动作=位移”的）。","【缺点】位移速度由动画决定，代码控制自由度降低。","【开关】Animator 组件勾选/取消【Apply Root Motion】。","【注意】Root Motion 需要动画片段里有根骨骼运动数据（烘焙的位移）。"],
   "tips":[{"t":"note","c":"简单判断：走路/跑步若动画自带“身体前倾+位移”，就用 Root Motion；纯原地动画则用代码移动。"}]},
  {"h":"配置与选择","lead":"何时用、怎么用。",
   "steps":["【启用】角色 Animator 勾选 Apply Root Motion，播放自带位移的动画，角色自动移动。","【代码移动二选一】用 Root Motion 后，别再用代码 transform 位移（会叠加冲突）。","【用 Root Motion 的方式】输入控制“动画状态”（走路/跑步），位移交给动画。","【混合方式】Root Motion 提供位移 + 代码只做转向/方向控制。","【关卡动画】过场动画/机关动画用 Root Motion 精确位移。","【禁用场景】走格子、精确操控（如小游戏）用代码位移更可控，取消 Apply Root Motion。","【根运动设置】动画片段的 Root Transform Rotation/Position 属性（第 129 课）控制根运动行为。","【验证】勾选后播放，观察角色是否随动画移动。"],
   "tips":[{"t":"success","c":"判断标准：动作自带位移（跑跳翻滚）→ Root Motion；动作原地（待机、攻击）→ 代码位移。"}]},
 ],
 "errors":[{"err":"勾了 Root Motion 但角色不动？","why":"动画片段没烘焙根位移","fix":"检查动画片段是否有根运动数据；或改用代码位移并取消 Root Motion。"}],
 "exercise":["体验跑步动画开启/关闭 Root Motion 的差异","理解哪些动作适合 Root Motion","正确选择角色的移动方案"],
 "summary":"Root Motion 已掌握。下一课学 2D 动画。"},

{"num":141,"title":"2D 动画（Sprite Animation）","summary":"掌握 2D 帧动画：多张序列帧做成动画，用于 2D 角色、UI、特效。","keywords":"2d动画,sprite animation,帧动画,序列帧,spriterenderer","time":"约 14 分钟","difficulty":"入门",
 "objectives":["理解 2D 帧动画原理","掌握制作序列帧动画","掌握代码控制"],
 "intro":"2D 游戏的“走路动画”其实是快速切换一组图片（序列帧）。本课制作第一个 2D 帧动画。",
 "sections":[
  {"h":"2D 帧动画原理","lead":"“翻页动画”。",
   "steps":["2D 动画 = 按顺序快速切换 Sprite（精灵图片），每秒 N 帧形成动感。","【素材】一组连续的精灵图（如角色走路的 8 帧）。","【制作方式】把一组 Sprite 拖到一个对象上，生成 Animation Clip。","【SpriteRenderer】2D 对象的显示组件（第 202 课），动画改变它的 sprite 属性。","【帧率】动画片段的时间轴决定播放速度，一般 8-12 帧/秒。","【特点】无需骨骼、简单直观，适合像素/手绘风格。","【对比】骨骼动画（2D 用 Spine/2D Animation 包）可变形更灵活，进阶。","【用途】角色动作、特效帧、UI 动画、翻页。"],
   "tips":[{"t":"note","c":"2D 帧动画 = 老式“翻页册”，简单高效，2D 游戏主力。"}]},
  {"h":"制作序列帧动画","lead":"上手做。",
   "steps":["【准备素材】导入一组精灵图（如 walk_0、walk_1...walk_7），设置 Texture Type 为 Sprite（第 39 课）。","【建对象】场景里创建空对象，加 SpriteRenderer，把第一帧 sprite 赋上。","【打开 Animation 窗口】选中对象，点 Create 命名 Walk，保存。","【添加关键帧】在时间轴 0 秒，把 SpriteRenderer 的 Sprite 属性设为第 1 帧，点添加关键帧。","【下一帧】时间轴移到 0.1 秒，Sprite 设为第 2 帧；重复直到最后一帧。","【循环】选中 .anim 勾选 Loop Time（第 129 课）。","【预览】播放：角色“走起来”了！","【快速法】在 Project 里多选所有帧图片，直接拖到场景/对象上，Unity 自动生成动画与 Animator（便捷方式）。","【优化】帧数越多越细腻但越占资源，按需。","【注意】帧的切换时间决定动作速度，可用“样条曲线”整体调快慢。"],
   "tips":[{"t":"success","c":"最省事路径：多选序列帧图片 → 拖到场景 → 自动成动画。一拖搞定。"}]},
 ],
 "errors":[{"err":"精灵动画不播放？","why":"SpriteRenderer 没被动画驱动，或 Loop 未开","fix":"确认动画片段记录了 Sprite 属性；勾选 Loop Time；确认 Animator 有该状态。"}],
 "exercise":["用一组序列帧制作走路动画","设置循环并调整播放速度","用代码 SetBool 控制行走/待机切换"],
 "summary":"2D 帧动画已掌握。下一课学代码控制动画。"},

{"num":142,"title":"动画控制器脚本控制（SetTrigger 等）","summary":"系统掌握用代码控制动画：参数、状态切换、播放暂停，实现完整动画逻辑。","keywords":"animator脚本,settrigger,播放控制,动画控制,代码控制动画","time":"约 14 分钟","difficulty":"入门",
 "objectives":["掌握 Animator 常用 API","实现参数驱动的状态切换","掌握播放/暂停控制"],
 "intro":"前几课零散用了 SetFloat/SetBool，本课系统整理 Animator 的代码控制全家桶。",
 "sections":[
  {"h":"Animator 核心 API","lead":"一套方法走天下。",
   "steps":["【获取】private Animator anim; void Awake() { anim = GetComponent<Animator>(); }","【Float】anim.SetFloat(\"Speed\", value); anim.SetFloat(\"Speed\", value, damp, deltaTime);（平滑）","【Int】anim.SetInteger(\"State\", 1);","【Bool】anim.SetBool(\"IsWalking\", true);","【Trigger】anim.SetTrigger(\"Attack\"); 触发一次性动作；anim.ResetTrigger(\"Attack\"); 手动复位。","【读取】float s = anim.GetFloat(\"Speed\"); bool b = anim.GetBool(\"IsWalking\");","【当前状态】anim.GetCurrentAnimatorStateInfo(0)（层 0）；检查是否在某状态：stateInfo.IsName(\"Walk\")。","【状态归一化时间】stateInfo.normalizedTime：动画播放进度（>1 表示循环过一轮）。","【播放/暂停】anim.speed = 0f（暂停）/ 1f（正常）；anim.Play(\"StateName\") 强制播放指定状态。","【层】anim.SetLayerWeight(1, w);（第 136 课）。"],
   "tips":[{"t":"note","c":"核心心法：参数是“开关”，Set 系列是“拨开关”，状态机负责“看开关换动画”。"}]},
  {"h":"实战：完整角色动画控制","lead":"组合使用。",
   "steps":["在角色移动脚本里整合：","float speed = new Vector3(h, 0, v).magnitude;","anim.SetFloat(\"Speed\", speed, 0.1f, Time.deltaTime); // 平滑","anim.SetBool(\"IsGrounded\", grounded);","if (Input.GetKeyDown(KeyCode.Space) && grounded) { anim.SetTrigger(\"Jump\"); }","if (Input.GetMouseButtonDown(0)) { anim.SetTrigger(\"Attack\"); }","【状态机配合】Speed>0.1 走路、IsGrounded=false 跳跃、Attack 触发攻击。","【动画完成回调】攻击结束回到待机：状态机的攻击→待机过渡（Has Exit Time 播完）即可，无需代码。","【打断】攻击中想被受击打断：Any State → Hit（第 131 课）。","【调试】把 anim 参数打出来确认在变：Debug.Log(anim.GetFloat(\"Speed\"));","【注意】SetTrigger 需状态机有对应过渡才生效；状态名与参数名要一致。"],
   "tips":[{"t":"success","c":"完整角色动画 = SetFloat 速度 + SetBool 状态 + SetTrigger 动作 + 状态机配合。一套齐活。"}]},
 ],
 "errors":[{"err":"攻击动画播不完就切走？","why":"过渡条件太快或 Has Exit Time 未配置","fix":"攻击→待机过渡勾选 Has Exit Time；或调整条件逻辑。"}],
 "exercise":["用代码完整驱动移动/跳跃/攻击动画","用 anim.Play 强制播放某个状态","用 anim.speed=0 实现动画暂停"],
 "summary":"动画代码控制已掌握。下一课学 IK 反向动力学。"},

{"num":143,"title":"IK 反向动力学","summary":"掌握 IK 原理与应用：让手/脚自动“够到”目标，实现抓取、踩坡等效果。","keywords":"ik,反向动力学,inverse kinematics,瞄准,手脚目标,onanimatorik","time":"约 14 分钟","difficulty":"入门",
 "objectives":["理解 IK 概念","掌握 OnAnimatorIK","实现手抓取/脚踩地"],
 "intro":"“手要抓到门把手”“脚要踩在斜坡上”——正向动画做不到，靠 IK（反向动力学）根据目标反推骨骼姿态。",
 "sections":[
  {"h":"IK 概念","lead":"“从结果反推姿势”。",
   "steps":["【正向动力学 FK】动画直接指定骨骼旋转，手就到哪算哪。","【反向动力学 IK】给定“手要到达的点”，系统反算肩肘手腕的旋转让手够到。","【典型应用】手抓物体、脚踩地形、视线看目标、头部跟随。","【人形 IK】Unity 人形模型内置 IK 支持（必须 Humanoid + Avatar）。","【触发时机】在 OnAnimatorIK(int layerIndex) 方法里写 IK 逻辑（每帧动画更新时调用）。","【前提】脚本挂角色上，且角色 Animator 是 Humanoid。","【层】OnAnimatorIK 的 layerIndex 参数对应当前动画层。"],
   "tips":[{"t":"note","c":"IK = “目标点 → 反推姿势”。它让角色“够得着”“踩得稳”。"}]},
  {"h":"实现手抓取与脚踩地","lead":"实战两例。",
   "steps":["【手抓取】在角色脚本里写：","public Transform handTarget; // 要抓的目标（如门把手）","public float handWeight = 1f;","void OnAnimatorIK(int layerIndex) {","Animator anim = GetComponent<Animator>();","if (handTarget != null) {","anim.SetIKPositionWeight(AvatarIKGoal.RightHand, handWeight);","anim.SetIKRotationWeight(AvatarIKGoal.RightHand, handWeight);","anim.SetIKPosition(AvatarIKGoal.RightHand, handTarget.position);","anim.SetIKRotation(AvatarIKGoal.RightHand, handTarget.rotation);","}","}","【脚踩地形】用射线检测脚下地面高度，设置双脚 IK：","anim.SetIKPositionWeight(AvatarIKGoal.LeftFoot, 1f);","anim.SetIKPosition(AvatarIKGoal.LeftFoot, footPos);","【权重】Weight 0-1 控制 IK 影响程度（可平滑过渡）。","【AvatarIKGoal】枚举：LeftHand/RightHand/LeftFoot/RightFoot/LeftShoulder 等。","【注意】IK 在动画之上叠加，权重 0=纯动画、1=完全 IK。","【调试】用 Debug.DrawRay 画出 IK 目标点。","【性能】IK 计算有成本，按需启用（近处才开）。"],
   "tips":[{"t":"success","c":"IK 公式：SetIKPositionWeight(目标, 权重) + SetIKPosition(目标, 点)。两行实现“够得到”。"}]},
 ],
 "errors":[{"err":"IK 没效果？","why":"模型不是 Humanoid、或权重为 0、或没在 OnAnimatorIK 里写","fix":"确认 Humanoid+Avatar；权重设 1；方法名写对 OnAnimatorIK。"}],
 "exercise":["实现右手抓取一个目标点","用射线让脚贴合地面坡度","用权重做 IK 淡入淡出"],
 "summary":"IK 已掌握。下一课学布娃娃 Ragdoll。"},

{"num":144,"title":"布娃娃 Ragdoll","summary":"利用 Ragdoll：让角色被击飞时“瘫软”，实现真实倒地与物理死亡效果。","keywords":"布娃娃,ragdoll,物理角色,倒地,死亡物理","time":"约 14 分钟","difficulty":"入门",
 "objectives":["理解布娃娃原理","创建布娃娃","实现死亡触发布娃娃"],
 "intro":"角色中弹后“瘫软倒地”——布娃娃（Ragdoll）把角色的骨骼变成物理关节，失去控制时自然倒下。",
 "sections":[
  {"h":"布娃娃原理","lead":"“让骨骼变成物理摆”。",
   "steps":["【原理】把角色各骨骼（头、四肢）变成“刚体+碰撞体+关节”，由物理模拟控制。","【正常时】Animator 控制骨骼，布娃娃禁用；死亡时启用布娃娃，物理接管。","【效果】中弹/爆炸后角色“瘫倒”，四肢自然摆动，很真实。","【制作方式】Unity 提供自动生成器：GameObject → 3D Object → Ragdoll...，按提示指定骨骼即可生成。","【组成部分】每段骨骼：Rigidbody + Capsule/Box Collider + Character Joint。","【骨骼映射】需要 Humanoid 模型并正确配置 Avatar。","【注意】布娃娃较耗性能，只给“会死”的重要角色用。"],
   "tips":[{"t":"note","c":"布娃娃 = 把“演员”的骨头换成“物理玩偶”，动画不管时物理接管。"}]},
  {"h":"创建与触发布娃娃","lead":"三步接入。",
   "steps":["【自动生成】把带 Humanoid 的模型放入场景，选中后菜单 GameObject → 3D Object → Ragdoll...。","在弹出的窗口里，把模型的各骨骼对象拖到对应槽（Pelvis 骨盆、Left Hips 左大腿...）。","点击【Create】，Unity 自动给骨骼添加刚体/碰撞体/关节。","【默认状态】生成后角色会瘫倒（因为布娃娃激活了）——我们要先“禁用布娃娃”。","【禁用】把所有布娃娃的 Rigidbody 设为 isKinematic（或挂脚本统一管理），让动画恢复控制。","【死亡触发】脚本里写：","public RagdollController ragdoll;","void Die() { ragdoll.Activate(); /* 停掉 Animator */ anim.enabled = false; }","【Activate 实现】遍历所有布娃娃 Rigidbody：rb.isKinematic = false; rb.useGravity = true;","【复活】反向设置 isKinematic = true + 启用 Animator + 复位 Transform。","【注意】触发时先停 Animator 再激活布娃娃，避免动画与物理抢骨骼。","【调试】用“骨撞声”等物理材质配合更真实。"],
   "tips":[{"t":"success","c":"布娃娃接入 = 生成器生成 → 默认禁用 → 死亡时激活并停 Animator。"}]},
 ],
 "errors":[{"err":"角色一进场景就瘫倒？","why":"布娃娃默认激活","fix":"脚本在 Start 里把所有 Rigidbody 设为 isKinematic，让动画接管；死亡时再激活。"}],
 "exercise":["用生成器给角色创建布娃娃","实现“死亡时激活布娃娃”","（进阶）实现复活与动画恢复"],
 "summary":"布娃娃已掌握。下一课综合练习：角色动画状态机。"},

{"num":145,"title":"综合练习：完整角色动画状态机","summary":"综合动画全部知识，搭建待机/移动/跳跃/攻击/受击/死亡的完整状态机。","keywords":"综合练习,角色状态机,动画整合,实战,完整动画","time":"约 25 分钟","difficulty":"入门",
 "objectives":["综合运用动画章知识","搭建完整角色状态机","实现参数驱动的动画切换"],
 "intro":"把动画章所有能力整合：一个角色，六种状态、参数驱动、平滑过渡。这是动画章毕业项目！",
 "sections":[
  {"h":"准备素材","lead":"角色 + 动画片段。",
   "steps":["导入一个 Humanoid 角色模型（带基础动画或商店下载）。","确认 Rig=Humanoid、Avatar 配置成功（第 138 课）。","准备动画片段：Idle（待机）、Walk（走路）、Run（跑步）、Jump（跳跃）、Attack（攻击）、Hit（受击）、Dead（死亡）。","建议用商店“免费人形动画包”，或让角色模型自带。","【混合树】把 Walk/Run 做进一个 1D 混合树（Speed 参数），第 134 课。","把动画片段整理进 Animations 文件夹。"],
   "tips":[{"t":"note","c":"没有现成动画也没关系：用 Animation 窗口自己录 Idle/Walk 基础版也能练。"}]},
  {"h":"搭建状态机","lead":"六状态 + 参数 + 过渡。",
   "steps":["创建 Animator Controller，命名 CharacterAnim。","【状态】创建 6 个状态并绑定动画：Idle、Move（混合树）、Jump、Attack、Hit、Dead。","【参数】添加：Speed（Float）、IsGrounded（Bool）、Attack（Trigger）、IsDead（Bool）、IsHit（Bool）。","【过渡】","Idle ↔ Move：Speed>0.1 / Speed<0.1。","Move → Jump：IsGrounded=false；Jump → Idle：IsGrounded=true。","Any State → Hit：IsHit=true；Hit → Idle：播完（Has Exit Time）。","Any State → Dead：IsDead=true。","【注意】Jump 在空中不可切攻击？可加限制（进阶）。","【初始状态】Idle 设为默认。","【过渡时长】0.1-0.15 秒平滑。"],
   "tips":[{"t":"note","c":"状态机“画”好后，重点在过渡条件是否互斥清晰。"}]},
  {"h":"代码驱动与测试","lead":"让角色动起来。",
   "steps":["挂 CharacterControl 脚本（第 142 课整合版）：","public float speed = 4f;","void Update() {","float h = Input.GetAxis(\"Horizontal\"); float v = Input.GetAxis(\"Vertical\");","Vector3 move = new Vector3(h, 0, v);","anim.SetFloat(\"Speed\", move.magnitude, 0.1f, Time.deltaTime);","if (move != Vector3.zero) transform.rotation = Quaternion.LookRotation(move);","bool grounded = Physics.Raycast(transform.position, Vector3.down, 0.2f);","anim.SetBool(\"IsGrounded\", grounded);","if (Input.GetKeyDown(KeyCode.Space) && grounded) { anim.SetTrigger(\"Jump\"); rb.AddForce(Vector3.up * 8f, ForceMode.Impulse); }","if (Input.GetMouseButtonDown(0)) { anim.SetTrigger(\"Attack\"); }","if (Input.GetKeyDown(KeyCode.H)) { anim.SetBool(\"IsHit\", true); }","if (Input.GetKeyDown(KeyCode.K)) { anim.SetBool(\"IsDead\", true); }","}","播放测试：WASD 走动/跑步、空格跳、左键攻击、H 受击、K 死亡。","逐个验证每个状态与过渡，调整 Duration 与条件。","检查无报错，保存场景与动画控制器。","【完成】你的角色已经“会表演”了！"],
   "tips":[{"t":"success","c":"动画章毕业：从录关键帧到完整状态机，你已掌握游戏动画的 90% 核心能力。"}]},
 ],
 "errors":[{"err":"受击后无法恢复？","why":"Hit 状态的过渡没设好","fix":"Hit→Idle 过渡勾选 Has Exit Time；或用 Trigger 而非 Bool 复位。"}],
 "exercise":["完成六状态完整状态机","用参数驱动全部切换并测试","（进阶）把 Walk/Run 合并成混合树"],
 "summary":"角色状态机完成！动画章毕业。下一章进入 UI 界面系统，为游戏加上“脸面”。"},

# ============ 第10章 UI 界面系统 (146-170) ============
{"num":146,"title":"Canvas 画布与 UI 基础","summary":"掌握 Canvas 画布：UI 的容器、渲染模式、缩放模式，理解 UI 工作方式。","keywords":"canvas,画布,ui,渲染模式,screen space,缩放","time":"约 15 分钟","difficulty":"入门",
 "objectives":["理解 Canvas 作用","掌握三种渲染模式","掌握 Canvas Scaler"],
 "intro":"所有 UI（按钮、文字、血条）都必须放在 Canvas 画布里。本课把画布彻底讲清楚。",
 "sections":[
  {"h":"创建 Canvas","lead":"UI 的“画板”。",
   "steps":["【创建】Hierarchy 右键 → UI → Canvas（或创建任意 UI 元素会自动生成 Canvas + EventSystem）。","【结构】Canvas 下会有子物体（如 Button 的子物体 Text）；EventSystem 自动创建。","【Canvas 组件】核心组件：Render Mode（渲染模式）。","【Screen Space - Overlay（默认）】：UI 永远显示在最上层，不参与 3D 遮挡，最简单常用。","【Screen Space - Camera】：UI 放在指定相机的渲染上，可做“随场景缩放的 3D 效果 UI”。","【World Space】：UI 变成世界中的 3D 物体（血条悬在头顶、VR 界面）。","【Canvas Scaler】组件控制 UI 随屏幕缩放（下一步）。","【注意】UI 元素必须挂在 Canvas（或其子对象）下才能显示。"],
   "tips":[{"t":"note","c":"99% 的 2D 游戏 UI 用 Overlay 模式；角色头顶血条用 World Space。"}]},
  {"h":"Canvas Scaler 缩放模式","lead":"不同屏幕大小 UI 不乱。",
   "steps":["Canvas 默认带【Canvas Scaler】组件，控制 UI 缩放。","【UI Scale Mode】三种：","① Constant Pixel Size：固定像素大小，UI 在不同分辨率下像素不变（小屏可能被裁）。","② Scale With Screen Size：按参考分辨率缩放，UI 自适应（推荐，主流）。","【参考分辨率】设 Reference Resolution，如 1920x1080。","【匹配 Match】0=按宽缩放、1=按高缩放、0.5=取平均。手游竖屏常用 0.5。","③ Constant Physical Size：按物理尺寸，多用于印刷/特殊设备。","【安全区 Safe Area】全面屏手机避开刘海（进阶，可用 Safe Area 组件）。","【实战】设 Scale With Screen Size + 1920x1080 + Match 0.5，改 Game 视图分辨率测试 UI 不散。","【参考】UI 设计稿一般按 1920x1080 做。"],
   "tips":[{"t":"success","c":"Canvas Scaler = UI 的“自适应开关”，Scale With Screen Size 是首选。"}]},
 ],
 "errors":[{"err":"UI 元素看不见？","why":"没放在 Canvas 下、或 Camera 设置问题","fix":"确认元素是 Canvas 的子物体；Overlay 模式下检查 Canvas 是否被禁用。"}],
 "exercise":["创建 Canvas 并认识结构","切换三种渲染模式观察差异","配置 Canvas Scaler 让 UI 自适应"],
 "summary":"Canvas 已掌握。下一课学事件系统。"},

{"num":147,"title":"事件系统 EventSystem","summary":"掌握 EventSystem：UI 的“神经中枢”，理解点击/悬停事件如何传递。","keywords":"event system,事件系统,raycaster,standalone input module,ui事件","time":"约 12 分钟","difficulty":"入门",
 "objectives":["理解 EventSystem 作用","掌握常用 UI 事件接口","理解事件传递"],
 "intro":"为什么鼠标能“点中”按钮？全靠 EventSystem。本课搞懂 UI 事件的机制。",
 "sections":[
  {"h":"EventSystem 组件","lead":"UI 的“总管”。",
   "steps":["【自动创建】创建 UI 时自动生成 EventSystem 对象，含 EventSystem + StandaloneInputModule 组件。","【EventSystem】负责“谁是当前选中的 UI”、“事件怎么派发”。","【Standalone Input Module】把鼠标/键盘/触摸转换成 UI 事件（点击、悬停、拖拽）。","【删除后果】删除 EventSystem 后，所有 UI 点击失效！","【Graphic Raycaster】Canvas 自带，负责“射线命中”：判断鼠标点中了哪个 UI 元素。","【事件流向】鼠标位置 → Raycaster 找命中的 UI → EventSystem 派发事件给该元素（及其上的监听脚本）。","【重要】UI 元素要能被点击：要有 Graphic（Image/Text）且 Raycast Target 勾选。"],
   "tips":[{"t":"danger","c":"EventSystem 千万别删！删了 UI 全“失灵”，这是新手高频事故。"}]},
  {"h":"UI 事件接口","lead":"不用按钮也能响应 UI 事件。",
   "steps":["把脚本挂到 UI 元素上，实现对应接口即可接收事件：","【IPointerClickHandler】点击：void OnPointerClick(PointerEventData e)","【IPointerEnterHandler】进入：OnPointerEnter","【IPointerExitHandler】离开：OnPointerExit","【IPointerDownHandler】按下：OnPointerDown","【IDragHandler】拖拽：OnDrag","【IDropHandler】放下：OnDrop","【IBeginDragHandler / IEndDragHandler】拖拽开始/结束","【写法示例】","using UnityEngine.EventSystems;","public class ClickTest : MonoBehaviour, IPointerClickHandler { public void OnPointerClick(PointerEventData e) { Debug.Log(\"点击了我！\"); } }","【注意】脚本挂的 UI 元素需可被射线命中（Image 有 Raycast Target）。","【EventData】PointerEventData 里有鼠标位置、点击数量等。","【进阶】IPointerEnter/Exit 常用来做“悬停变色/放大”。","【UI 事件 vs 按钮】按钮是“预包装”的点击；接口是“自由定制”的事件。"],
   "tips":[{"t":"success","c":"EventSystem + 接口 = 无限 UI 交互：悬停、拖拽、右键、长按都能做。"}]},
 ],
 "errors":[{"err":"UI 拖拽/点击不响应？","why":"EventSystem 缺失、元素无 Graphic、或 Raycast Target 未勾选","fix":"确认 EventSystem 存在；UI 元素有 Image/Text；Graphic 的 Raycast Target 勾选。"}],
 "exercise":["用 IPointerClickHandler 实现点击打印","用 IPointerEnter/Exit 实现悬停变色","说出 EventSystem 三个组件的职责"],
 "summary":"事件系统已掌握。下一课学 Text 文本。"},

{"num":148,"title":"Text 文本与文字排版","summary":"掌握 TextMeshPro 文本：创建、字体、字号、颜色、富文本、排版。","keywords":"text,textmeshpro,文本,富文本,排版,文字","time":"约 14 分钟","difficulty":"入门",
 "objectives":["掌握 TextMeshPro 创建","掌握文本属性","掌握富文本"],
 "intro":"游戏里的对话、提示、分数都要文字。本课用 TextMeshPro（TMP）把文字玩明白。",
 "sections":[
  {"h":"创建 TextMeshPro 文本","lead":"TMP 是 UI 文字的标准。",
   "steps":["【创建】Hierarchy 右键 → UI → Text - TextMeshPro。","【首次提示】弹出“Import TMP Essentials”，点【Import TMP Essentials】导入基础资源。","【输入文字】选中文本对象，Inspector 的【Text Input】里输入“你好，Unity！”。","【字体】TextMeshPro 需要“字体资产”（TMP Font Asset）；默认 Arial 支持中文可能不全。","【导入中文字体】导入 TTF 字体 → 选中字体 → Create → TextMeshPro → Font Asset，生成 TMP 字体资产（第 41 课）。","【指定字体】把 TMP 字体资产拖到文本的 Font Asset 槽。","【字号】Font Size：文字大小（如 36）。","【颜色】Color 选文字颜色；加描边/阴影：勾选 Underlay/Outline 设置。","【对齐】Alignment：水平/垂直对齐（左上、居中…）。","【换行】TMP 自动换行（有宽度限制）；Wrapping 开启。","【富文本】默认支持：<b>粗体</b>、<i>斜体</i>、<color=red>红字</color>、<size=60>大</size>。","【代码改字】tmpro.text = \"分数：\" + score;（第 167 课）。"],
   "tips":[{"t":"note","c":"TMP 富文本让“一句话里多种颜色/大小”零成本，注意 <color=#FF0000> 十六进制也可。"}]},
  {"h":"排版与布局","lead":"让文字整齐。",
   "steps":["【Rect Transform】文本大小由 RectTransform 控制，拖拽四角调整宽高。","【自动调整】勾选 TMP 组件的【Auto Size】可自动缩放到合适大小（显示不全时缩小）。","【首行缩进/段落】Paragraph Spacing、Line Spacing 等控制行距段距。","【字符间距】Character Spacing 调整字间距。","【水平/垂直溢出】Overflow 设为 Overflow 显示全（超出）；或 Ellipsis 截断加省略号。","【分层】文字在 Canvas 内的顺序由 Hierarchy 顺序决定（后画的在上层）。","【多行】宽限制内自动换行，回车强制换行。","【排版技巧】用“空格+换行”做简单对齐；复杂排版用 Layout Group（第 156 课）。","【注意】TMP 的 Sorting Order 与 Canvas 层级共同决定显示顺序。"],
   "tips":[{"t":"success","c":"TMP 三件套：字体资产、字号、富文本，覆盖 90% 文字需求。"}]},
 ],
 "errors":[{"err":"中文显示为方块？","why":"字体不支持中文","fix":"用支持中文的 TTF 字体生成 TMP 字体资产并指定。"}],
 "exercise":["创建 TMP 文本并显示中文","用富文本做“红色大号”文字","用代码更新文本内容"],
 "summary":"TextMeshPro 已掌握。下一课学 Image 图片。"},

{"num":149,"title":"Image 图片与 UI 背景","summary":"掌握 Image 组件：设置图片、九宫格切片、颜色、填充，做 UI 视觉。","keywords":"image,ui图片,图片,九宫格,sliced,filled,背景","time":"约 14 分钟","difficulty":"入门",
 "objectives":["掌握 Image 组件","掌握九宫格切片","掌握 Filled 填充"],
 "intro":"UI 的背景、图标、按钮底色都是 Image。本课把 Image 组件的核心功能讲透。",
 "sections":[
  {"h":"Image 基础","lead":"给 UI 上“画布”。",
   "steps":["【创建】Hierarchy 右键 → UI → Image，创建一张默认白色图片。","【改图】Image 组件的【Source Image】槽里拖入一张 Sprite 图片（需 Texture Type=Sprite，第 39 课）。","【颜色】Color：给图片染色（白色图可染任意色，是常用技巧）。","【材质 Material】可加 UI 材质（渐变、描边等，进阶）。","【Image Type 类型】","① Simple 简单：整图缩放。","② Sliced 九宫格：四角不变、中间拉伸（圆角/边框 UI 必备）。","③ Tiled 平铺：图片重复填充。","④ Filled 填充：按比例显示部分（血条/进度条的底层实现）。","【Preserve Aspect】保持宽高比（防止变形）。","【Raycast Target】是否接收点击（纯装饰图可关掉，避免挡住按钮）。"],
   "tips":[{"t":"note","c":"白色方块图 = “万能染布”：染任意色做背景、按钮底，超常用。"}]},
  {"h":"九宫格与填充实战","lead":"两个最常用的 Image 技巧。",
   "steps":["【九宫格】在 Project 选中 Sprite 图片 → Inspector → Sprite Editor 打开编辑器。","在 Sprite Editor 里拖动四条绿线设置【九宫格边距】。","设置后，把 Image Type 选【Sliced】：圆角/边框在缩放时不拉伸变形。","返回场景：拉伸该图片，四角保持圆角、中间拉伸——做按钮背景超好用。","【填充（血条）】创建 Image 作为血条背景，Source Image 用白色方块，颜色红色。","再建一个子 Image 作为血条填充（绿色），Image Type 选【Filled】。","【Fill Method】Horizontal；【Fill Amount】0-1 控制填充比例。","代码控制血条：fill.fillAmount = hp / maxHp;（第 160 课完整血条）。","【注意】九宫格需要 Sprite 本身带边框数据（Sprite Editor 设置）。"],
   "tips":[{"t":"success","c":"Sliced 做“不变形的边框”，Filled 做“能伸缩的血条”，两大王牌。"}]},
 ],
 "errors":[{"err":"图片拖不进 Source Image？","why":"图片 Texture Type 不是 Sprite","fix":"选中图片，Texture Type 改为 Sprite (2D and UI)，Apply。"}],
 "exercise":["用 Image + 白色方块染出彩色背景","用 Sprite Editor 设九宫格做圆角按钮底","用 Filled 做一个简单血条"],
 "summary":"Image 已掌握。下一课学 Button 按钮。"},

{"num":150,"title":"Button 按钮详解","summary":"系统掌握按钮：状态、过渡效果、导航、点击事件、动态生成。","keywords":"button,按钮,过渡,interactable,onclick,按钮状态","time":"约 15 分钟","difficulty":"入门",
 "objectives":["掌握按钮组件","掌握过渡效果","掌握动态按钮"],
 "intro":"按钮是 UI 交互的“主力”。本课把它从上到下讲透：状态、效果、事件、动态生成。",
 "sections":[
  {"h":"Button 组件属性","lead":"认识按钮的“身体”。",
   "steps":["创建 UI → Button - TextMeshPro，得到按钮对象（含 Image + Button 组件 + TMP 子物体）。","【Interactable 可交互】勾选则可点；取消则按钮变“禁用”状态（变灰/不可点）。","【Transition 过渡】按钮在不同状态下的视觉效果：","① Color Tint（默认）：不同状态变颜色。","Target Graphic：应用过渡的图片；Normal/Highlighted/Pressed/Selected/Disabled 五色。","② Sprite Swap：换图（需要多张状态图）。","③ Animation：自定义动画（用 Animator）。","【Navigation】键盘/手柄导航：默认 Automatic（自动判断上下左右）；可设为 None 禁用。","【On Click ()】点击事件列表：加监听、绑方法（第 123 课）。"],
   "tips":[{"t":"note","c":"默认 Color Tint 最省事；想要“发光/放大”效果用 Sprite Swap 或 Animation。"}]},
  {"h":"动态创建与批量按钮","lead":"代码生成按钮。",
   "steps":["【代码创建】需要 using UnityEngine.UI; 与 TMPro;","Button newBtn = GameObject.Find(\"Canvas\").AddComponent<Button>();（先有 Image）","更常用：从预制体实例化按钮（第 76 课）然后绑定事件。","【事件传参】批量生成多个按钮时，给每个按钮绑定不同参数：","for (int i = 0; i < 5; i++) {","Button b = Instantiate(btnPrefab, parent).GetComponent<Button>();","int level = i + 1; // 捕获循环变量","b.onClick.AddListener(delegate { LoadLevel(level); });","b.GetComponentInChildren<TMP_Text>().text = \"关卡 \" + level;","}","【注意】循环里用局部变量捕获 i（int level = i+1），否则所有按钮都读到最后一个 i。","【布局】配合 Layout Group 自动排列（第 156 课）。","【禁用单个】b.interactable = false;（未解锁关卡灰显）。","【实战】做一个“关卡选择”界面：5 个按钮，点击进入对应关卡。"],
   "tips":[{"t":"success","c":"批量按钮三件套：循环实例化 + AddListener 传参 + 局部变量捕获，搞定关卡选择。"}]},
 ],
 "errors":[{"err":"循环创建的按钮都触发同一个参数？","why":"闭包捕获了循环变量","fix":"在循环体里用局部变量复制 i 再传给委托。"}],
 "exercise":["配置按钮五种状态颜色","做一个被禁用（interactable=false）的按钮","批量生成 5 个带不同参数的事件按钮"],
 "summary":"Button 已掌握。下一课学 Slider 滑动条。"},
]
